-- Transfer $100 from Alice (id=1) to Bob (id=2)
BEGIN;

UPDATE accounts SET balance = balance - 100 WHERE id = 1;
UPDATE accounts SET balance = balance + 100 WHERE id = 2;

-- Check the result (within the same transaction)
SELECT id, balance FROM accounts WHERE id IN (1, 2);

COMMIT;  -- make it permanent
-- Or: ROLLBACK;  -- undo everything since BEGIN

-- Error handling with savepoints
BEGIN;
  INSERT INTO orders (user_id, total) VALUES (5, 99.99);
  SAVEPOINT order_created;
  INSERT INTO order_items (order_id, product_id) VALUES (currval('orders_id_seq'), 99);  -- fails
ROLLBACK TO SAVEPOINT order_created;  -- undo only to the savepoint
  -- handle the error, try again with different product_id
COMMIT;
